/**
 * AI Invoice Pipeline API
 * POST /api/accounting/ai-invoice-pipeline
 * Body: { documentId } — processes a captured document into a supplier invoice
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import {
  validatePipelineInput,
  matchSupplierFromExtraction,
  buildInvoiceFromExtraction,
  determineApprovalRoute,
  computePipelineConfidence,
  type PipelineThresholds,
} from '@/modules/accounting/services/aiInvoicePipelineService';
import type { ExtractedDocument } from '@/modules/accounting/types/documentCapture.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = Record<string, any>;

const DEFAULT_THRESHOLDS: PipelineThresholds = {
  autoApproveConfidence: 0.95,
  routeApprovalConfidence: 0.85,
  highValueAmount: 100000,
  lowValueAutoApproveAmount: 5000,
};

async function handler(req: CompanyApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return apiResponse.methodNotAllowed(res, req.method || '', ['POST']);

  const { companyId } = req;
  const userId: string = req.user?.id || req.user?.userId || '';
  const { documentId } = req.body as { documentId?: string };

  if (!documentId) return apiResponse.badRequest(res, 'documentId is required');

  // Fetch captured document
  const [doc] = (await sql`
    SELECT extracted_data, status FROM captured_documents
    WHERE id = ${documentId}::uuid AND company_id = ${companyId}
  `) as Row[];

  if (!doc) return apiResponse.notFound(res, 'Captured document', documentId);
  if (!doc.extracted_data) return apiResponse.badRequest(res, 'Document has no extracted data');

  const extracted = doc.extracted_data as ExtractedDocument;

  // Validate
  const validation = validatePipelineInput(extracted);
  if (!validation.valid) {
    return apiResponse.badRequest(res, `Validation failed: ${validation.errors.join(', ')}`);
  }

  // Match supplier
  const suppliers = (await sql`
    SELECT id, name FROM suppliers WHERE company_id = ${companyId} AND is_active = true
  `) as Row[];

  const supplierMatch = matchSupplierFromExtraction(extracted, suppliers.map(s => ({ id: s.id, name: s.name })));

  if (!supplierMatch) {
    return apiResponse.success(res, {
      status: 'manual_review',
      reason: `No matching supplier found for "${extracted.vendorName}"`,
      extractedVendor: extracted.vendorName,
      confidence: 0,
    });
  }

  // Build invoice
  const invoiceInput = buildInvoiceFromExtraction(extracted, supplierMatch.supplierId);
  const pipelineConfidence = computePipelineConfidence(extracted, supplierMatch);
  const approvalRoute = determineApprovalRoute(pipelineConfidence, invoiceInput.totalAmount, DEFAULT_THRESHOLDS);

  // Create supplier invoice
  const [invoice] = (await sql`
    INSERT INTO supplier_invoices (
      company_id, invoice_number, supplier_id, invoice_date, due_date,
      subtotal, tax_rate, tax_amount, total_amount, payment_terms,
      reference, status, created_by
    ) VALUES (
      ${companyId}, ${invoiceInput.invoiceNumber}, ${supplierMatch.supplierId}::uuid,
      ${invoiceInput.invoiceDate}::date, ${invoiceInput.dueDate || null}::date,
      ${invoiceInput.totalAmount - invoiceInput.taxAmount}, ${invoiceInput.taxRate},
      ${invoiceInput.taxAmount}, ${invoiceInput.totalAmount},
      ${invoiceInput.paymentTerms || 'net30'}, ${invoiceInput.reference || null},
      ${approvalRoute === 'auto_approve' ? 'approved' : 'draft'},
      ${userId}
    ) RETURNING id, invoice_number, status
  `) as Row[];

  if (!invoice) return apiResponse.internalError(res, null, 'Failed to create invoice');

  // Link document to invoice
  await sql`
    UPDATE captured_documents
    SET matched_invoice_id = ${invoice.id}::uuid, status = 'matched'
    WHERE id = ${documentId}::uuid
  `;

  log.info('AI Invoice Pipeline completed', {
    documentId, invoiceId: invoice.id, supplierMatch: supplierMatch.supplierName,
    confidence: pipelineConfidence, route: approvalRoute,
  }, 'ai-pipeline');

  return apiResponse.success(res, {
    invoice: { id: invoice.id, invoiceNumber: invoice.invoice_number, status: invoice.status },
    supplierMatch: { name: supplierMatch.supplierName, confidence: supplierMatch.confidence },
    pipelineConfidence,
    approvalRoute,
    warnings: validation.warnings,
  });
}


export default withCompany(withErrorHandler(handler));

/**
 * POST /api/onboarding/extract
 * Accepts a base64 document image and calls the VLM (configured via
 * VLM_MODEL env var) to extract company registration details.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import { pdfToImage } from '@/lib/pdf-to-image';

export const config = {
  api: { bodyParser: { sizeLimit: '20mb' } },
};

// ── VLM config ────────────────────────────────────────────────────────────────

const VLM_BASE_URL  = process.env.VLLM_BASE_URL;
if (!VLM_BASE_URL) throw new Error('VLLM_BASE_URL environment variable is required');
const VLM_MODEL     = process.env.VLM_MODEL ?? process.env.VLLM_MODEL;
if (!VLM_MODEL) throw new Error('VLM_MODEL environment variable is required');
const VLM_API_KEY   = process.env.VLLM_API_KEY    ?? 'EMPTY';
const VLM_TIMEOUT   = parseInt(process.env.VLLM_TIMEOUT ?? '120000', 10);

const SYSTEM_PROMPT = `You are a document data extraction assistant specialised in South African business \
documents (CIPC certificates, letterheads, company registrations, VAT certificates). \
Extract structured company information from the provided document image and return ONLY a valid \
JSON object — no markdown, no prose, no explanation. \
If a field cannot be found, return an empty string for that field. \

IMPORTANT field definitions: \
- "name": The official REGISTERED NAME of the company exactly as it appears on the CIPC certificate \
  (e.g. "BRIGHTSPHERE TECHNOLOGIES (PTY) LTD"). This is the legal entity name, NOT the trading name. \
  On CIPC certificates this is labelled "Registered Name" or "Enterprise Name". \
- "tradingName": The trading name or brand name if different from the registered name. \
  On CIPC certificates this may appear as "Trading Name" or "Business Name". \

Return the JSON object with exactly these keys: \
name, tradingName, registrationNumber, vatNumber, taxNumber, \
addressLine1, addressLine2, city, province, postalCode, country, \
phone, email, website, directors. \
The "directors" field must be an array of objects with keys: name, idNumber, role. \
Extract all directors/members listed on the document. If none are listed, return an empty array.`;

const USER_PROMPT = `Extract all company details from this document. \
CRITICAL: The "name" field must be the official REGISTERED NAME (legal entity name) as shown on the document, \
not the trading name. Look for labels like "Registered Name", "Enterprise Name", or "Company Name". \
Also extract: trading name, CIPC registration number (e.g. 2005/023519/07), VAT number, \
income tax reference number, physical/postal address, phone, email, website, \
and all listed directors or members with their full names, ID/passport numbers, and roles (Director, Member, etc). \
Respond with only the JSON object.`;

// ── Extracted data type ───────────────────────────────────────────────────────

interface ExtractedDirector {
  name: string;
  idNumber: string;
  role: string;
}

interface ExtractedCompany {
  name: string;
  tradingName: string;
  registrationNumber: string;
  vatNumber: string;
  taxNumber: string;
  addressLine1: string;
  addressLine2: string;
  city: string;
  province: string;
  postalCode: string;
  country: string;
  phone: string;
  email: string;
  website: string;
  directors: ExtractedDirector[];
}

function parseVlmJson(raw: string): ExtractedCompany {
  // Strip ```json ... ``` fences if present
  const stripped = raw
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```\s*$/, '')
    .trim();

  const parsed: unknown = JSON.parse(stripped);

  if (typeof parsed !== 'object' || parsed === null) {
    throw new Error('VLM returned non-object JSON');
  }

  const obj = parsed as Record<string, unknown>;

  const str = (key: string): string =>
    typeof obj[key] === 'string' ? (obj[key] as string) : '';

  /**
   * Normalize ALL-CAPS text to Title Case.
   * Preserves: (Pty) Ltd, (PTY) LTD → (Pty) Ltd, CC, NPC, Inc
   * Only transforms if the string is predominantly uppercase.
   */
  const titleCase = (s: string): string => {
    if (!s) return s;
    const alphaChars = s.replace(/[^a-zA-Z]/g, '');
    if (!alphaChars) return s;
    const upperRatio = alphaChars.replace(/[^A-Z]/g, '').length / alphaChars.length;
    if (upperRatio < 0.7) return s; // already mixed case — leave it

    const KEEP_UPPER = new Set(['pty', 'ltd', 'cc', 'npc', 'inc', 'llc', 'bv', 'sa']);
    return s
      .split(/(\s+|[()]+)/)
      .map(word => {
        const lower = word.toLowerCase();
        if (KEEP_UPPER.has(lower)) return word.charAt(0).toUpperCase() + lower.slice(1);
        if (/^\s+$/.test(word) || /^[()]+$/.test(word)) return word;
        return lower.replace(/^\w/, c => c.toUpperCase());
      })
      .join('');
  };

  return {
    name:               titleCase(str('name')),
    tradingName:        titleCase(str('tradingName')),
    registrationNumber: str('registrationNumber'),
    vatNumber:          str('vatNumber'),
    taxNumber:          str('taxNumber'),
    addressLine1:       titleCase(str('addressLine1')),
    addressLine2:       titleCase(str('addressLine2')),
    city:               titleCase(str('city')),
    province:           titleCase(str('province')),
    postalCode:         str('postalCode'),
    country:            str('country') || 'South Africa',
    phone:              str('phone'),
    email:              str('email'),
    website:            str('website'),
    directors:          parseDirectors(obj.directors, titleCase),
  };
}

function parseDirectors(
  raw: unknown,
  titleCase: (s: string) => string,
): ExtractedDirector[] {
  if (!Array.isArray(raw)) return [];
  return raw
    .filter((d): d is Record<string, unknown> => typeof d === 'object' && d !== null)
    .map(d => ({
      name:     titleCase(typeof d.name === 'string' ? d.name : ''),
      idNumber: typeof d.idNumber === 'string' ? d.idNumber : '',
      role:     titleCase(typeof d.role === 'string' ? d.role : 'Director'),
    }))
    .filter(d => d.name.length > 0);
}

// ── Handler ───────────────────────────────────────────────────────────────────

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method!, ['POST']);
  }

  const { image } = req.body as { image?: unknown };

  if (typeof image !== 'string' || !image.startsWith('data:')) {
    return apiResponse.badRequest(res, 'image must be a base64 data URL string');
  }

  log.info('VLM extract request received', { size: image.length }, 'onboarding/extract');

  // ── PDF → PNG conversion ──────────────────────────────────────────────────
  let imageForVlm: string = image;

  if (image.startsWith('data:application/pdf')) {
    log.info('PDF detected — converting first page to PNG', {}, 'onboarding/extract');
    try {
      imageForVlm = await pdfToImage(image);
      log.info('PDF converted to PNG', { size: imageForVlm.length }, 'onboarding/extract');
    } catch (pdfErr: unknown) {
      const msg = pdfErr instanceof Error ? pdfErr.message : String(pdfErr);
      log.error('PDF conversion failed', { msg }, 'onboarding/extract');
      return apiResponse.error(
        res,
        'SERVICE_UNAVAILABLE' as never,
        'Could not convert the PDF for AI extraction. Please try a JPEG or PNG instead.',
      );
    }
  }

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), VLM_TIMEOUT);

  let vlmText: string;

  try {
    const vlmRes = await fetch(`${VLM_BASE_URL}/chat/completions`, {
      method: 'POST',
      signal: controller.signal,
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${VLM_API_KEY}`,
      },
      body: JSON.stringify({
        model: VLM_MODEL,
        messages: [
          { role: 'system', content: SYSTEM_PROMPT },
          {
            role: 'user',
            content: [
              { type: 'text',      text: USER_PROMPT },
              { type: 'image_url', image_url: { url: imageForVlm } },
            ],
          },
        ],
        max_tokens: 2000,
        temperature: 0.1,
      }),
    });

    clearTimeout(timer);

    if (!vlmRes.ok) {
      const body = await vlmRes.text();
      log.error('VLM request failed', { status: vlmRes.status, body }, 'onboarding/extract');
      return apiResponse.error(
        res,
        'SERVICE_UNAVAILABLE' as never,
        'AI extraction is currently unavailable. Please enter details manually.',
      );
    }

    const vlmBody = await vlmRes.json() as {
      choices?: Array<{ message?: { content?: string } }>;
    };

    vlmText = vlmBody.choices?.[0]?.message?.content ?? '';

    if (!vlmText) {
      return apiResponse.badRequest(res, 'VLM returned an empty response');
    }
  } catch (err: unknown) {
    clearTimeout(timer);
    const isAbort = err instanceof Error && err.name === 'AbortError';
    log.error('VLM fetch error', { err }, 'onboarding/extract');
    return apiResponse.error(
      res,
      'SERVICE_UNAVAILABLE' as never,
      isAbort
        ? 'AI extraction timed out. Please try again or enter details manually.'
        : 'AI extraction is currently unavailable. Please enter details manually.',
    );
  }

  let extracted: ExtractedCompany;
  try {
    extracted = parseVlmJson(vlmText);
  } catch (parseErr) {
    log.error('VLM JSON parse error', { vlmText, parseErr }, 'onboarding/extract');
    return apiResponse.badRequest(
      res,
      'AI extraction returned an unexpected format. Please enter details manually.',
    );
  }

  log.info('VLM extract success', { name: extracted.name }, 'onboarding/extract');
  return apiResponse.success(res, extracted);
}


export default withAuth(withErrorHandler(handler));

/**
 * /onboarding — 7-step company setup wizard with Smart Setup pre-step.
 * Standalone layout (no AppLayout), matches login dark theme.
 */

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import {
  Check, Building2, MapPin, Image, Landmark,
  Settings, FileText, ChevronLeft, ChevronRight, Loader2,
} from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import {
  type WizardData, INITIAL_WIZARD,
  Step1, Step2, Step3, Step4, Step5, Step6, Step7,
} from '@/components/onboarding/WizardSteps';
import { SmartSetupChoice } from '@/components/onboarding/SmartSetupChoice';

const STEPS = [
  { icon: Building2, title: 'Company Details',       sub: 'Tell us about your business' },
  { icon: MapPin,    title: 'Address & Contact',      sub: 'Where can we reach you?' },
  { icon: Image,     title: 'Logo Upload',            sub: 'Brand your workspace' },
  { icon: Landmark,  title: 'Banking Details',        sub: 'Your primary bank account' },
  { icon: Settings,  title: 'Financial Preferences',  sub: 'Year-end, VAT & currency' },
  { icon: FileText,  title: 'Statutory Documents',    sub: 'Upload key certificates' },
  { icon: Check,     title: 'Review & Complete',      sub: 'Confirm and get started' },
];

export default function OnboardingWizard() {
  const router = useRouter();

  // step === -1 is the Smart Setup pre-step (choice screen)
  const [step, setStep]             = useState(-1);
  const [d, setD]                   = useState<WizardData>(INITIAL_WIZARD);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError]           = useState('');
  const [authChecked, setAuthChecked] = useState(false);

  // Auth check — then verify user doesn't already have companies (e.g. via invitation)
  useEffect(() => {
    apiFetch('/api/auth/me').then(async (r) => {
      if (!r.ok) { void router.replace('/login'); return; }
      const body = await r.json();
      if (body.data?.onboardingCompleted) { void router.replace('/accounting'); return; }

      // Invited users already have a company — skip onboarding for them
      try {
        const compRes = await apiFetch('/api/accounting/companies?action=user-companies');
        if (compRes.ok) {
          const compBody = await compRes.json();
          const companies: unknown[] = compBody.data ?? [];
          if (companies.length > 0) {
            await apiFetch('/api/onboarding/complete', { method: 'POST' });
            void router.replace('/accounting');
            return;
          }
        }
      } catch {
        // Non-fatal — fall through to show the wizard
      }

      setAuthChecked(true);
    }).catch(() => void router.replace('/login'));
  }, [router]);

  const set = useCallback(<K extends keyof WizardData>(k: K, v: WizardData[K]) => {
    setD(prev => ({ ...prev, [k]: v }));
  }, []);

  // Smart Setup: merge extracted fields and jump to step 0
  const handleExtracted = useCallback((extracted: Partial<WizardData>) => {
    setD(prev => ({ ...prev, ...extracted }));
    setStep(0);
  }, []);

  const hasCipc     = d.documents.some(doc => doc.type === 'cipc_certificate');
  const canContinue = step === 0 ? d.name.trim().length > 0
                    : step === 5 ? hasCipc   // CIPC is required on documents step
                    : true;
  const isLast      = step === STEPS.length - 1;
  const skippable   = step >= 1 && step <= 4; // steps 1-4 skippable, step 5 (documents) not
  const isPreStep   = step === -1;

  const next = () => { if (canContinue) setStep(s => Math.min(s + 1, STEPS.length - 1)); };
  const back = () => setStep(s => Math.max(s - 1, 0));

  const handleSubmit = async () => {
    setSubmitting(true);
    setError('');
    try {
      // 1. Create company
      const compRes = await apiFetch('/api/accounting/companies', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: d.name, tradingName: d.tradingName,
          registrationNumber: d.registrationNumber, vatNumber: d.vatNumber,
          taxNumber: d.taxNumber, addressLine1: d.addressLine1,
          addressLine2: d.addressLine2, city: d.city, province: d.province,
          postalCode: d.postalCode, country: d.country, phone: d.phone,
          email: d.email, website: d.website, logoData: d.logoData || undefined,
          bankName: d.bankName || undefined,
          bankAccountNumber: d.bankAccountNumber || undefined,
          bankBranchCode: d.bankBranchCode || undefined,
          bankAccountType: d.bankAccountType,
          financialYearStart: d.financialYearStart,
          vatPeriod: d.vatPeriod, defaultCurrency: d.defaultCurrency,
        }),
      });
      if (!compRes.ok) {
        const body = await compRes.json();
        throw new Error(body.error?.message || 'Failed to create company');
      }
      const compData = await compRes.json();
      const companyId = compData.data?.id;

      // 2. Save directors (non-blocking)
      if (d.directors.length > 0 && companyId) {
        try {
          await apiFetch('/api/accounting/company-directors', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'X-Company-Id': companyId },
            body: JSON.stringify({ directors: d.directors }),
          });
        } catch { /* non-critical */ }
      }

      // 3. Upload documents (non-blocking — company is already created)
      if (d.documents.length > 0 && companyId) {
        try {
          await apiFetch('/api/onboarding/documents', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ companyId, documents: d.documents }),
          });
        } catch { /* non-critical */ }
      }

      // 4. Mark onboarding complete
      await apiFetch('/api/onboarding/complete', { method: 'POST' });

      // 4. Navigate — full reload so the middleware picks up the new ff_onboarding_done cookie
      window.location.href = '/accounting';
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Something went wrong');
      setSubmitting(false);
    }
  };

  if (!authChecked) {
    return (
      <div className="min-h-screen bg-gray-950 flex items-center justify-center">
        <Loader2 className="w-8 h-8 text-teal-500 animate-spin" />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-950 text-white px-4 py-8">
      {/* Logo */}
      <div className="max-w-2xl mx-auto mb-8">
        <img src="/logo.png" alt="ISAFlow" className="h-10 w-auto brightness-0 invert" />
      </div>

      {/* Progress — only shown during the 7-step wizard (step 0-6) */}
      {!isPreStep && (
        <div className="max-w-2xl mx-auto mb-8">
          <div className="flex items-center justify-between">
            {STEPS.map((s, i) => (
              <div key={i} className="flex items-center flex-1 last:flex-none">
                <button
                  onClick={() => i < step && setStep(i)}
                  disabled={i > step}
                  className={`w-9 h-9 rounded-full flex items-center justify-center text-sm font-medium shrink-0 transition-colors ${
                    i < step  ? 'bg-teal-600 text-white cursor-pointer' :
                    i === step ? 'bg-teal-500 text-white ring-2 ring-teal-400' :
                    'bg-gray-800 text-gray-500'
                  }`}
                >
                  {i < step ? <Check className="w-4 h-4" /> : i + 1}
                </button>
                {i < STEPS.length - 1 && (
                  <div className={`h-0.5 flex-1 mx-1 ${i < step ? 'bg-teal-600' : 'bg-gray-800'}`} />
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Pre-step: Smart Setup choice */}
      {isPreStep && (
        <SmartSetupChoice
          onManual={() => setStep(0)}
          onExtracted={handleExtracted}
        />
      )}

      {/* Wizard card */}
      {!isPreStep && (
        <div className="max-w-2xl mx-auto">
          <div className="mb-4">
            <h2 className="text-xl font-semibold">{STEPS[step]?.title}</h2>
            <p className="text-sm text-gray-400">{STEPS[step]?.sub}</p>
          </div>

          <div className="bg-gray-900 border border-gray-700 rounded-2xl p-6 shadow-xl min-h-[320px]">
            {step === 0 && <Step1 d={d} set={set} />}
            {step === 1 && <Step2 d={d} set={set} />}
            {step === 2 && <Step3 d={d} set={set} />}
            {step === 3 && <Step4 d={d} set={set} />}
            {step === 4 && <Step5 d={d} set={set} />}
            {step === 5 && <Step6 d={d} set={set} />}
            {step === 6 && <Step7 d={d} />}
          </div>

          {/* Error */}
          {error && (
            <div className="mt-4 px-3 py-2.5 bg-red-500/10 border border-red-500/30 rounded-lg">
              <p className="text-sm text-red-400">{error}</p>
            </div>
          )}

          {/* Navigation */}
          <div className="flex justify-between mt-6">
            <button
              onClick={step === 0 ? () => setStep(-1) : back}
              className="flex items-center gap-1.5 text-sm text-gray-400 hover:text-white transition-colors"
            >
              <ChevronLeft className="w-4 h-4" /> Back
            </button>
            <div className="flex gap-3">
              {skippable && !isLast && (
                <button onClick={next} className="text-sm text-gray-400 hover:text-white transition-colors">
                  Skip
                </button>
              )}
              {isLast ? (
                <button
                  onClick={() => void handleSubmit()}
                  disabled={submitting}
                  className="flex items-center gap-2 bg-teal-600 hover:bg-teal-500 disabled:bg-teal-800 text-white font-medium text-sm px-6 py-2.5 rounded-lg transition-colors"
                >
                  {submitting ? <><Loader2 className="w-4 h-4 animate-spin" /> Saving...</> : 'Complete Setup'}
                </button>
              ) : (
                <button
                  onClick={next}
                  disabled={!canContinue}
                  className="flex items-center gap-1.5 bg-teal-600 hover:bg-teal-500 disabled:bg-teal-800 disabled:cursor-not-allowed text-white font-medium text-sm px-5 py-2.5 rounded-lg transition-colors"
                >
                  Continue <ChevronRight className="w-4 h-4" />
                </button>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * Smart Setup pre-step: choose between manual entry and document upload.
 * Upload mode shows individual doc slots with CIPC mandatory for AI extraction.
 */

import { useRef, useState } from 'react';
import { Keyboard, ScanLine, Upload, Loader2, CheckCircle2, AlertCircle, FileText } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import type { WizardData, DocFile } from './WizardSteps';
import { DOC_SLOTS } from './WizardSteps';

interface Props {
  onManual: () => void;
  onExtracted: (data: Partial<WizardData>) => void;
}

type ExtractState =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'success' }
  | { status: 'error'; message: string };

function fileToDataUrl(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload  = () => resolve(reader.result as string);
    reader.onerror = () => reject(new Error('Failed to read file'));
    reader.readAsDataURL(file);
  });
}

const ALLOWED = ['image/jpeg', 'image/png', 'image/webp', 'image/gif', 'application/pdf'];

export function SmartSetupChoice({ onManual, onExtracted }: Props) {
  const fileRefs = useRef<Record<string, HTMLInputElement | null>>({});
  const [showUploadArea, setShowUploadArea] = useState(false);
  const [docs, setDocs] = useState<DocFile[]>([]);
  const [extractState, setExtractState] = useState<ExtractState>({ status: 'idle' });

  const cipcDoc = docs.find(d => d.type === 'cipc_certificate');
  const isLoading = extractState.status === 'loading';
  const isSuccess = extractState.status === 'success';

  const addDoc = async (slotType: string, file: File) => {
    if (!ALLOWED.includes(file.type)) return;
    if (file.size > 20 * 1024 * 1024) return;
    const dataUrl = await fileToDataUrl(file);
    const newDoc: DocFile = { type: slotType, name: file.name, data: dataUrl, mimeType: file.type, size: file.size };
    setDocs(prev => [...prev.filter(d => d.type !== slotType), newDoc]);
  };

  const removeDoc = (type: string) => setDocs(prev => prev.filter(d => d.type !== type));

  const handleExtract = async () => {
    if (!cipcDoc) return;
    setExtractState({ status: 'loading' });

    try {
      const res = await apiFetch('/api/onboarding/extract', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ image: cipcDoc.data }),
      });
      const body = await res.json() as { success: boolean; data?: Partial<WizardData>; error?: { message?: string } };

      if (!res.ok || !body.success) {
        setExtractState({ status: 'error', message: body.error?.message ?? 'AI extraction failed.' });
        return;
      }

      setExtractState({ status: 'success' });
      setTimeout(() => {
        onExtracted({ ...body.data, documents: docs });
      }, 800);
    } catch {
      setExtractState({ status: 'error', message: 'AI extraction is currently unavailable. Please enter details manually.' });
    }
  };

  const handleSkipExtract = () => {
    // Pass uploaded docs to the wizard without AI extraction
    onExtracted({ documents: docs });
  };

  return (
    <div className="max-w-2xl mx-auto">
      <div className="mb-6 text-center">
        <h2 className="text-xl font-semibold text-white">How would you like to set up?</h2>
        <p className="text-sm text-gray-400 mt-1">
          Get started in seconds with AI extraction, or fill in details yourself.
        </p>
      </div>

      {/* Choice cards */}
      {!showUploadArea && (
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <button onClick={onManual}
            className="group flex flex-col items-center gap-3 bg-gray-800 border border-gray-700 hover:border-teal-500 rounded-2xl p-6 text-center transition-all duration-200 hover:shadow-lg hover:shadow-teal-500/10">
            <div className="w-12 h-12 rounded-xl bg-gray-700 group-hover:bg-teal-600/20 flex items-center justify-center transition-colors">
              <Keyboard className="w-6 h-6 text-gray-400 group-hover:text-teal-400 transition-colors" />
            </div>
            <p className="font-semibold text-white text-sm">Enter Details Manually</p>
            <p className="text-xs text-gray-400">Enter your company information step by step</p>
          </button>

          <button onClick={() => setShowUploadArea(true)}
            className="group flex flex-col items-center gap-3 bg-gray-800 border border-gray-700 hover:border-teal-500 rounded-2xl p-6 text-center transition-all duration-200 hover:shadow-lg hover:shadow-teal-500/10">
            <div className="w-12 h-12 rounded-xl bg-gray-700 group-hover:bg-teal-600/20 flex items-center justify-center transition-colors">
              <ScanLine className="w-6 h-6 text-gray-400 group-hover:text-teal-400 transition-colors" />
            </div>
            <p className="font-semibold text-white text-sm">Upload Documents</p>
            <p className="text-xs text-gray-400">Upload your CIPC certificate and other docs — we&apos;ll extract the details</p>
          </button>
        </div>
      )}

      {/* Upload area with document slots */}
      {showUploadArea && (
        <div className="bg-gray-800 border border-gray-700 rounded-2xl p-6">
          {isLoading && (
            <div className="flex flex-col items-center gap-3 py-6">
              <Loader2 className="w-10 h-10 text-teal-500 animate-spin" />
              <p className="text-sm text-gray-300 font-medium">Analysing CIPC certificate...</p>
              <p className="text-xs text-gray-500">Extracting company details — this may take up to 30 seconds</p>
            </div>
          )}

          {isSuccess && (
            <div className="flex flex-col items-center gap-3 py-6">
              <CheckCircle2 className="w-10 h-10 text-teal-400" />
              <p className="text-sm text-gray-300 font-medium">Details extracted!</p>
              <p className="text-xs text-gray-500">Opening your pre-filled form...</p>
            </div>
          )}

          {!isLoading && !isSuccess && (
            <>
              <p className="text-sm text-gray-300 mb-4">Upload your company documents. CIPC certificate is required for AI extraction.</p>

              <div className="grid gap-3">
                {DOC_SLOTS.map(slot => {
                  const doc = docs.find(d => d.type === slot.type);
                  return (
                    <div key={slot.type} className={`border rounded-lg p-3 ${slot.required && !doc ? 'border-teal-500/50 bg-teal-500/5' : 'border-gray-700'}`}>
                      <div className="flex items-center justify-between">
                        <div className="flex items-center gap-2">
                          <FileText className="w-4 h-4 text-gray-500" />
                          <span className="text-sm text-gray-300">{slot.label}</span>
                          {slot.required && <span className="text-xs bg-teal-600/20 text-teal-400 px-1.5 py-0.5 rounded">Required</span>}
                        </div>
                        {doc ? (
                          <div className="flex items-center gap-2">
                            <span className="text-xs text-gray-400">{doc.name}</span>
                            <button onClick={() => removeDoc(slot.type)} className="text-xs text-red-400 hover:text-red-300">Remove</button>
                          </div>
                        ) : (
                          <label className="flex items-center gap-1.5 cursor-pointer text-xs text-teal-400 hover:text-teal-300">
                            <Upload className="w-3.5 h-3.5" /> Upload
                            <input type="file" className="hidden" accept="image/*,application/pdf"
                              ref={el => { fileRefs.current[slot.type] = el; }}
                              onChange={e => { const f = e.target.files?.[0]; if (f) { void addDoc(slot.type, f); } e.target.value = ''; }} />
                          </label>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>

              {extractState.status === 'error' && (
                <div className="mt-4 flex items-start gap-2 px-3 py-2.5 bg-red-500/10 border border-red-500/30 rounded-lg">
                  <AlertCircle className="w-4 h-4 text-red-400 shrink-0 mt-0.5" />
                  <p className="text-sm text-red-400">{extractState.message}</p>
                </div>
              )}

              <div className="flex items-center justify-between mt-5">
                <button onClick={() => { setShowUploadArea(false); setExtractState({ status: 'idle' }); setDocs([]); }}
                  className="text-sm text-gray-400 hover:text-white transition-colors">
                  Back
                </button>
                <div className="flex gap-3">
                  {docs.length > 0 && (
                    <button onClick={handleSkipExtract}
                      className="text-sm text-gray-400 hover:text-white transition-colors">
                      Skip Extraction
                    </button>
                  )}
                  <button onClick={() => void handleExtract()} disabled={!cipcDoc}
                    className="flex items-center gap-2 bg-teal-600 hover:bg-teal-500 disabled:bg-teal-800 disabled:cursor-not-allowed text-white text-sm font-medium px-4 py-2.5 rounded-lg transition-colors">
                    <ScanLine className="w-4 h-4" /> Extract Details
                  </button>
                </div>
              </div>
            </>
          )}
        </div>
      )}

      {showUploadArea && !isLoading && !isSuccess && (
        <p className="text-center text-xs text-gray-500 mt-4">
          Prefer to type?{' '}
          <button onClick={onManual} className="text-teal-400 hover:text-teal-300 underline">
            Enter details manually
          </button>
        </p>
      )}
    </div>
  );
}

/**
 * VLM Core — shared config, helpers, and type utilities
 * Used internally by vlmInvoiceService, vlmBankService, vlmStatutoryService.
 */

import { log } from '@/lib/logger';
import type { ExtractedLineItem, VendorBankDetails } from '@/modules/accounting/types/documentCapture.types';

// ---------------------------------------------------------------------------
// Config
// ---------------------------------------------------------------------------

export interface VlmConfig {
  baseUrl: string;
  model: string;
  apiKey: string;
  timeout: number;
}

export function getVlmConfig(): VlmConfig | null {
  const baseUrl = process.env.VLLM_BASE_URL;
  if (!baseUrl) return null;
  const apiKey = process.env.VLLM_API_KEY;
  if (!apiKey) throw new Error('VLLM_API_KEY is not configured');
  return {
    baseUrl: baseUrl.replace(/\/+$/, ''),
    model: process.env.VLM_MODEL || process.env.VLLM_MODEL || (() => { throw new Error('VLM_MODEL environment variable is required'); })(),
    apiKey,
    timeout: parseInt(process.env.VLLM_TIMEOUT || '120000', 10),
  };
}

/** Returns true if vLLM is configured */
export function isVlmAvailable(): boolean {
  return !!process.env.VLLM_BASE_URL;
}

// ---------------------------------------------------------------------------
// HTTP helper
// ---------------------------------------------------------------------------

export async function callVlmChat(
  config: VlmConfig,
  systemPrompt: string,
  userContent: Array<Record<string, unknown>>,
  maxTokens = 4096,
): Promise<string | null> {
  const body = {
    model: config.model,
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userContent },
    ],
    max_tokens: maxTokens,
    temperature: 0.1,
    stream: false,
  };

  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), config.timeout);

    const response = await fetch(`${config.baseUrl}/chat/completions`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${config.apiKey}`,
      },
      body: JSON.stringify(body),
      signal: controller.signal,
    });

    clearTimeout(timeoutId);

    if (!response.ok) {
      const errorText = await response.text().catch(() => 'unknown error');
      log.error('vLLM request failed', {
        status: response.status,
        error: errorText.substring(0, 500),
      }, 'vlm-core');
      return null;
    }

    const result = await response.json() as {
      choices?: Array<{ message?: { content?: string } }>;
    };
    return result.choices?.[0]?.message?.content ?? null;
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    if (msg.includes('aborted') || msg.includes('AbortError')) {
      log.error('vLLM request timed out', { timeout: config.timeout }, 'vlm-core');
    } else {
      log.error('vLLM request error', { error: msg }, 'vlm-core');
    }
    return null;
  }
}

