/**
 * Smart Setup pre-step: choose between manual entry and document upload.
 * Upload mode shows individual doc slots with CIPC mandatory for AI extraction.
 */

import { useRef, useState } from 'react';
import { Keyboard, ScanLine, Upload, Loader2, CheckCircle2, AlertCircle, FileText } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import type { WizardData, DocFile } from './WizardSteps';
import { DOC_SLOTS } from './WizardSteps';

interface Props {
  onManual: () => void;
  onExtracted: (data: Partial<WizardData>) => void;
}

type ExtractState =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'success' }
  | { status: 'error'; message: string };

function fileToDataUrl(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload  = () => resolve(reader.result as string);
    reader.onerror = () => reject(new Error('Failed to read file'));
    reader.readAsDataURL(file);
  });
}

const ALLOWED = ['image/jpeg', 'image/png', 'image/webp', 'image/gif', 'application/pdf'];

export function SmartSetupChoice({ onManual, onExtracted }: Props) {
  const fileRefs = useRef<Record<string, HTMLInputElement | null>>({});
  const [showUploadArea, setShowUploadArea] = useState(false);
  const [docs, setDocs] = useState<DocFile[]>([]);
  const [extractState, setExtractState] = useState<ExtractState>({ status: 'idle' });

  const cipcDoc = docs.find(d => d.type === 'cipc_certificate');
  const isLoading = extractState.status === 'loading';
  const isSuccess = extractState.status === 'success';

  const addDoc = async (slotType: string, file: File) => {
    if (!ALLOWED.includes(file.type)) return;
    if (file.size > 20 * 1024 * 1024) return;
    const dataUrl = await fileToDataUrl(file);
    const newDoc: DocFile = { type: slotType, name: file.name, data: dataUrl, mimeType: file.type, size: file.size };
    setDocs(prev => [...prev.filter(d => d.type !== slotType), newDoc]);
  };

  const removeDoc = (type: string) => setDocs(prev => prev.filter(d => d.type !== type));

  const handleExtract = async () => {
    if (!cipcDoc) return;
    setExtractState({ status: 'loading' });

    try {
      const res = await apiFetch('/api/onboarding/extract', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ image: cipcDoc.data }),
      });
      const body = await res.json() as { success: boolean; data?: Partial<WizardData>; error?: { message?: string } };

      if (!res.ok || !body.success) {
        setExtractState({ status: 'error', message: body.error?.message ?? 'AI extraction failed.' });
        return;
      }

      setExtractState({ status: 'success' });
      setTimeout(() => {
        onExtracted({ ...body.data, documents: docs });
      }, 800);
    } catch {
      setExtractState({ status: 'error', message: 'AI extraction is currently unavailable. Please enter details manually.' });
    }
  };

  const handleSkipExtract = () => {
    // Pass uploaded docs to the wizard without AI extraction
    onExtracted({ documents: docs });
  };

  return (
    <div className="max-w-2xl mx-auto">
      <div className="mb-6 text-center">
        <h2 className="text-xl font-semibold text-white">How would you like to set up?</h2>
        <p className="text-sm text-gray-400 mt-1">
          Get started in seconds with AI extraction, or fill in details yourself.
        </p>
      </div>

      {/* Choice cards */}
      {!showUploadArea && (
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <button onClick={onManual}
            className="group flex flex-col items-center gap-3 bg-gray-800 border border-gray-700 hover:border-teal-500 rounded-2xl p-6 text-center transition-all duration-200 hover:shadow-lg hover:shadow-teal-500/10">
            <div className="w-12 h-12 rounded-xl bg-gray-700 group-hover:bg-teal-600/20 flex items-center justify-center transition-colors">
              <Keyboard className="w-6 h-6 text-gray-400 group-hover:text-teal-400 transition-colors" />
            </div>
            <p className="font-semibold text-white text-sm">Enter Details Manually</p>
            <p className="text-xs text-gray-400">Enter your company information step by step</p>
          </button>

          <button onClick={() => setShowUploadArea(true)}
            className="group flex flex-col items-center gap-3 bg-gray-800 border border-gray-700 hover:border-teal-500 rounded-2xl p-6 text-center transition-all duration-200 hover:shadow-lg hover:shadow-teal-500/10">
            <div className="w-12 h-12 rounded-xl bg-gray-700 group-hover:bg-teal-600/20 flex items-center justify-center transition-colors">
              <ScanLine className="w-6 h-6 text-gray-400 group-hover:text-teal-400 transition-colors" />
            </div>
            <p className="font-semibold text-white text-sm">Upload Documents</p>
            <p className="text-xs text-gray-400">Upload your CIPC certificate and other docs — we&apos;ll extract the details</p>
          </button>
        </div>
      )}

      {/* Upload area with document slots */}
      {showUploadArea && (
        <div className="bg-gray-800 border border-gray-700 rounded-2xl p-6">
          {isLoading && (
            <div className="flex flex-col items-center gap-3 py-6">
              <Loader2 className="w-10 h-10 text-teal-500 animate-spin" />
              <p className="text-sm text-gray-300 font-medium">Analysing CIPC certificate...</p>
              <p className="text-xs text-gray-500">Extracting company details — this may take up to 30 seconds</p>
            </div>
          )}

          {isSuccess && (
            <div className="flex flex-col items-center gap-3 py-6">
              <CheckCircle2 className="w-10 h-10 text-teal-400" />
              <p className="text-sm text-gray-300 font-medium">Details extracted!</p>
              <p className="text-xs text-gray-500">Opening your pre-filled form...</p>
            </div>
          )}

          {!isLoading && !isSuccess && (
            <>
              <p className="text-sm text-gray-300 mb-4">Upload your company documents. CIPC certificate is required for AI extraction.</p>

              <div className="grid gap-3">
                {DOC_SLOTS.map(slot => {
                  const doc = docs.find(d => d.type === slot.type);
                  return (
                    <div key={slot.type} className={`border rounded-lg p-3 ${slot.required && !doc ? 'border-teal-500/50 bg-teal-500/5' : 'border-gray-700'}`}>
                      <div className="flex items-center justify-between">
                        <div className="flex items-center gap-2">
                          <FileText className="w-4 h-4 text-gray-500" />
                          <span className="text-sm text-gray-300">{slot.label}</span>
                          {slot.required && <span className="text-xs bg-teal-600/20 text-teal-400 px-1.5 py-0.5 rounded">Required</span>}
                        </div>
                        {doc ? (
                          <div className="flex items-center gap-2">
                            <span className="text-xs text-gray-400">{doc.name}</span>
                            <button onClick={() => removeDoc(slot.type)} className="text-xs text-red-400 hover:text-red-300">Remove</button>
                          </div>
                        ) : (
                          <label className="flex items-center gap-1.5 cursor-pointer text-xs text-teal-400 hover:text-teal-300">
                            <Upload className="w-3.5 h-3.5" /> Upload
                            <input type="file" className="hidden" accept="image/*,application/pdf"
                              ref={el => { fileRefs.current[slot.type] = el; }}
                              onChange={e => { const f = e.target.files?.[0]; if (f) { void addDoc(slot.type, f); } e.target.value = ''; }} />
                          </label>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>

              {extractState.status === 'error' && (
                <div className="mt-4 flex items-start gap-2 px-3 py-2.5 bg-red-500/10 border border-red-500/30 rounded-lg">
                  <AlertCircle className="w-4 h-4 text-red-400 shrink-0 mt-0.5" />
                  <p className="text-sm text-red-400">{extractState.message}</p>
                </div>
              )}

              <div className="flex items-center justify-between mt-5">
                <button onClick={() => { setShowUploadArea(false); setExtractState({ status: 'idle' }); setDocs([]); }}
                  className="text-sm text-gray-400 hover:text-white transition-colors">
                  Back
                </button>
                <div className="flex gap-3">
                  {docs.length > 0 && (
                    <button onClick={handleSkipExtract}
                      className="text-sm text-gray-400 hover:text-white transition-colors">
                      Skip Extraction
                    </button>
                  )}
                  <button onClick={() => void handleExtract()} disabled={!cipcDoc}
                    className="flex items-center gap-2 bg-teal-600 hover:bg-teal-500 disabled:bg-teal-800 disabled:cursor-not-allowed text-white text-sm font-medium px-4 py-2.5 rounded-lg transition-colors">
                    <ScanLine className="w-4 h-4" /> Extract Details
                  </button>
                </div>
              </div>
            </>
          )}
        </div>
      )}

      {showUploadArea && !isLoading && !isSuccess && (
        <p className="text-center text-xs text-gray-500 mt-4">
          Prefer to type?{' '}
          <button onClick={onManual} className="text-teal-400 hover:text-teal-300 underline">
            Enter details manually
          </button>
        </p>
      )}
    </div>
  );
}

/**
 * POST /api/auth/logout
 * Deletes the current user session from the database and clears the auth cookie.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { serialize } from 'cookie';
import { log } from '@/lib/logger';
import { apiResponse } from '@/lib/apiResponse';
import { verifyToken } from '@/lib/auth/jwt';
import { deleteSession } from '@/lib/auth/session';
import { AUTH_COOKIE_NAME } from '@/lib/auth/middleware';
import { withErrorHandler } from '@/lib/api-error-handler';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['POST']);
  }

  const token = req.cookies[AUTH_COOKIE_NAME];

  // Best-effort session deletion — don't fail if token is missing/invalid
  if (token) {
    try {
      const payload = await verifyToken(token);
      if (payload?.sessionId) {
        await deleteSession(payload.sessionId);
      }
    } catch (err) {
      log.warn('Failed to delete session during logout', { err }, 'auth/logout');
    }
  }

  // Clear the auth cookie and onboarding cookie on both domains
  const isProd = process.env.NODE_ENV === 'production';
  const secureSuffix = isProd ? '; Secure' : '';
  const clearOpts = {
    httpOnly: true,
    secure: isProd,
    sameSite: 'strict' as const,
    path: '/',
    maxAge: 0,
    expires: new Date(0),
  };
  res.setHeader('Set-Cookie', [
    // Clear auth cookie with .isaflow.co.za domain (for admin + app subdomains)
    serialize(AUTH_COOKIE_NAME, '', {
      ...clearOpts,
      ...(isProd ? { domain: '.isaflow.co.za' } : {}),
    }),
    // Clear auth cookie without domain (host-scoped, backward compat)
    serialize(AUTH_COOKIE_NAME, '', clearOpts),
    // Clear onboarding cookie with domain
    `ff_onboarding_done=; Path=/; Max-Age=0; SameSite=Lax${secureSuffix}${isProd ? '; Domain=.isaflow.co.za' : ''}`,
    // Clear onboarding cookie without domain (host-scoped)
    `ff_onboarding_done=; Path=/; Max-Age=0; SameSite=Lax${secureSuffix}`,
  ]);

  log.info('User logged out', {}, 'auth/logout');
  return apiResponse.success(res, null, 'Logged out successfully');
}

export default withErrorHandler(handler);

/**
 * Session Management
 * Database-backed session handling for token revocation and multi-device support
 */

import { sql } from '@/lib/neon';
import * as crypto from 'crypto';
import type { Session } from './types';

// Session expiry set to 1 day to approximate the 8h JWT ACCESS_TOKEN_EXPIRY.
// TODO: Implement a proper refresh-token flow so DB sessions and JWTs share the
// same expiry. Until then, the JWT expires first (8h) and the DB session row
// is cleaned up lazily. Setting 30d here created a window where a revoked JWT
// could not be fully invalidated via the session table.
const SESSION_EXPIRY_DAYS = 1;

/**
 * Create a hash of the token for storage
 * We don't store the actual token, just a hash for comparison
 */
function hashToken(token: string): string {
  return crypto.createHash('sha256').update(token).digest('hex');
}

/**
 * Create a new session for a user
 */
export async function createSession(
  userId: string,
  token: string,
  ipAddress?: string,
  userAgent?: string
): Promise<Session> {
  const tokenHash = hashToken(token);
  const expiresAt = new Date();
  expiresAt.setDate(expiresAt.getDate() + SESSION_EXPIRY_DAYS);

  const rows = await sql`
    INSERT INTO user_sessions (user_id, token_hash, expires_at, ip_address, user_agent)
    VALUES (${userId}, ${tokenHash}, ${expiresAt.toISOString()}, ${ipAddress || null}, ${userAgent || null})
    RETURNING id
  `;

  const sessionId = String(rows[0]?.id ?? '');

  return {
    id: sessionId,
    userId,
    tokenHash,
    expiresAt,
    createdAt: new Date(),
    ipAddress,
    userAgent,
  };
}

/**
 * Validate a session exists and is not expired
 */
export async function validateSession(
  sessionId: string,
  token: string
): Promise<boolean> {
  const tokenHash = hashToken(token);

  const result = await sql`
    SELECT id, expires_at
    FROM user_sessions
    WHERE id = ${sessionId}
      AND token_hash = ${tokenHash}
      AND expires_at > NOW()
  `;

  return result.length > 0;
}

/**
 * Get session by ID
 */
export async function getSession(sessionId: string): Promise<Session | null> {
  const result = await sql`
    SELECT id, user_id, token_hash, expires_at, created_at, ip_address, user_agent
    FROM user_sessions
    WHERE id = ${sessionId}
      AND expires_at > NOW()
  `;

  const row = result[0];
  if (!row) return null;

  return {
    id: row.id as string,
    userId: row.user_id as string,
    tokenHash: row.token_hash as string,
    expiresAt: new Date(row.expires_at as string),
    createdAt: new Date(row.created_at as string),
    ipAddress: row.ip_address as string | undefined,
    userAgent: row.user_agent as string | undefined,
  };
}

/**
 * Delete a specific session (logout)
 */
export async function deleteSession(sessionId: string): Promise<void> {
  await sql`
    DELETE FROM user_sessions
    WHERE id = ${sessionId}
  `;
}

/**
 * Delete all sessions for a user (logout everywhere)
 */
export async function deleteAllUserSessions(userId: string): Promise<void> {
  await sql`
    DELETE FROM user_sessions
    WHERE user_id = ${userId}
  `;
}

/**
 * Get all active sessions for a user
 */
export async function getUserSessions(userId: string): Promise<Session[]> {
  const result = await sql`
    SELECT id, user_id, token_hash, expires_at, created_at, ip_address, user_agent
    FROM user_sessions
    WHERE user_id = ${userId}
      AND expires_at > NOW()
    ORDER BY created_at DESC
  `;

  return result.map((row) => ({
    id: row.id,
    userId: row.user_id,
    tokenHash: row.token_hash,
    expiresAt: new Date(row.expires_at),
    createdAt: new Date(row.created_at),
    ipAddress: row.ip_address,
    userAgent: row.user_agent,
  }));
}

/**
 * Clean up expired sessions (run periodically)
 */
export async function cleanupExpiredSessions(): Promise<number> {
  const result = await sql`
    DELETE FROM user_sessions
    WHERE expires_at < NOW()
    RETURNING id
  `;

  return result.length;
}

/**
 * Extend session expiry (refresh)
 */
export async function extendSession(sessionId: string): Promise<void> {
  const expiresAt = new Date();
  expiresAt.setDate(expiresAt.getDate() + SESSION_EXPIRY_DAYS);

  await sql`
    UPDATE user_sessions
    SET expires_at = ${expiresAt.toISOString()}
    WHERE id = ${sessionId}
  `;
}

/**
 * POST /api/auth/login
 * Authenticates a user with email + password.
 * On success: signs a JWT, creates a DB session, sets an HttpOnly cookie.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { serialize } from 'cookie';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { apiResponse } from '@/lib/apiResponse';
import { verifyPassword } from '@/lib/auth/password';
import { signToken } from '@/lib/auth/jwt';
import { createSession } from '@/lib/auth/session';
import { AUTH_COOKIE_NAME } from '@/lib/auth/middleware';
import type { AuthRole } from '@/lib/auth/types';
import { get2FAStatus, isTrustedDevice } from '@/modules/auth/services/twoFactorService';
import { checkRateLimit } from '@/lib/rateLimit';
import { withErrorHandler } from '@/lib/api-error-handler';
type Row = Record<string, unknown>;

// Real bcrypt hash of 'timing-safe-dummy' at cost 12, used for constant-time rejection.
const TIMING_SAFE_HASH = '$2a$12$K4GByFHHbpZQKxVKzPEfXOdQuGfe0gPISQEFMEfcrrKjAXBgmC.Xq';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['POST']);
  }

  // Rate limit: 5 attempts per IP per 15 minutes
  // Use the last x-forwarded-for entry (proxy-appended) to prevent client IP spoofing.
  const ip: string = (() => {
    const forwarded = req.headers['x-forwarded-for'];
    if (forwarded) {
      const raw = Array.isArray(forwarded) ? forwarded[0] ?? '' : forwarded;
      const ips = raw.split(',').map((s: string) => s.trim());
      return ips[ips.length - 1] || req.socket.remoteAddress || 'unknown';
    }
    return req.socket.remoteAddress || 'unknown';
  })();
  if (checkRateLimit(ip, { windowMs: 15 * 60 * 1000, maxRequests: 5 })) {
    return res.status(429).json({
      success: false,
      error: { code: 'RATE_LIMITED', message: 'Too many attempts. Please try again later.' },
    });
  }

  const { email, password, deviceFingerprint } = req.body as {
    email?: string;
    password?: string;
    deviceFingerprint?: string;
  };

  if (!email || !password) {
    return apiResponse.badRequest(res, 'Email and password are required');
  }

  try {
    // Look up user by email
    const rows = (await sql`
      SELECT id, email, password_hash, first_name, last_name, role,
             is_active, permissions, profile_picture, department, onboarding_completed,
             failed_login_attempts, locked_until
      FROM users
      WHERE email = ${email.toLowerCase().trim()}
      LIMIT 1
    `) as Row[];

    const user = rows[0];

    if (!user) {
      // Constant-time failure — avoid timing attacks
      await verifyPassword(password, TIMING_SAFE_HASH);
      return res.status(401).json({
        success: false,
        error: { code: 'INVALID_CREDENTIALS', message: 'Invalid email or password' },
      });
    }

    if (!user.is_active) {
      return res.status(403).json({
        success: false,
        error: { code: 'ACCOUNT_INACTIVE', message: 'Account is disabled' },
      });
    }

    // Check account lockout
    if (user.locked_until) {
      const lockedUntil = user.locked_until instanceof Date ? user.locked_until : new Date(user.locked_until as string);
      if (lockedUntil > new Date()) {
        const minutesRemaining = Math.ceil((lockedUntil.getTime() - Date.now()) / 60000);
        return res.status(403).json({
          success: false,
          error: {
            code: 'ACCOUNT_LOCKED',
            message: `Account locked due to too many failed attempts. Try again in ${minutesRemaining} minute(s).`,
          },
        });
      }
    }

    // Verify password
    const passwordValid = await verifyPassword(password, user.password_hash as string);
    if (!passwordValid) {
      // Increment failed attempts; lock after 10 failures
      const attempts = ((user.failed_login_attempts as number) ?? 0) + 1;
      if (attempts >= 10) {
        await sql`
          UPDATE users
          SET failed_login_attempts = ${attempts},
              locked_until = NOW() + INTERVAL '30 minutes'
          WHERE id = ${user.id as string}
        `;
        log.warn('Account locked after failed attempts', { userId: user.id, attempts }, 'auth/login');
      } else {
        await sql`
          UPDATE users SET failed_login_attempts = ${attempts} WHERE id = ${user.id as string}
        `;
      }
      return res.status(401).json({
        success: false,
        error: { code: 'INVALID_CREDENTIALS', message: 'Invalid email or password' },
      });
    }

    // Check 2FA before creating a full session
    const twoFAStatus = await get2FAStatus(String(user.id));
    if (twoFAStatus.enabled) {
      // Check if device is already trusted
      const trusted = deviceFingerprint
        ? await isTrustedDevice(String(user.id), deviceFingerprint)
        : false;

      if (!trusted) {
        // Issue a short-lived temp token (5 min) — no DB session yet
        const tempAuthUser = {
          id: String(user.id),
          userId: String(user.id),
          email: user.email as string,
          firstName: (user.first_name as string) || '',
          lastName: (user.last_name as string) || '',
          name: '',
          role: user.role as AuthRole,
          permissions: [],
          isActive: true,
        };
        const tempToken = await signToken(tempAuthUser, '2fa-pending', '5m');
        log.info('2FA required — temp token issued', { userId: user.id }, 'auth/login');
        return res.status(200).json({
          success: true,
          data: { requiresTwoFactor: true, tempToken },
        });
      }
    }

    const firstName = (user.first_name as string) || '';
    const lastName = (user.last_name as string) || '';

    const authUser = {
      id: String(user.id),
      userId: String(user.id),
      email: user.email as string,
      firstName,
      lastName,
      name: `${firstName} ${lastName}`.trim() || (user.email as string),
      role: user.role as AuthRole,
      permissions: (user.permissions as string[]) || [],
      isActive: true,
      profilePicture: user.profile_picture as string | undefined,
      department: user.department as string | undefined,
    };

    // Sign JWT and create DB session — reuse the already-resolved safe IP
    const ipAddress = ip;
    const userAgent = req.headers['user-agent'];

    // Reset failed login attempts on successful password verification
    await sql`
      UPDATE users SET failed_login_attempts = 0, locked_until = NULL WHERE id = ${authUser.id}
    `;

    // Create session first, then sign token with the real sessionId
    // We pass a temporary token to createSession, then update the hash
    const tempToken = await signToken(authUser, 'pending');
    const session = await createSession(authUser.id, tempToken, ipAddress, userAgent);

    // Re-sign token with the real sessionId
    const finalToken = await signToken(authUser, session.id);

    // Update session with the hash of the final token
    const crypto = await import('crypto');
    const finalHash = crypto.createHash('sha256').update(finalToken).digest('hex');
    await sql`
      UPDATE user_sessions SET token_hash = ${finalHash} WHERE id = ${Number(session.id)}
    `;

    // Set HttpOnly cookie — 8h session, always secure
    const isProd = process.env.NODE_ENV === 'production';
    const authCookieString = serialize(AUTH_COOKIE_NAME, finalToken, {
      httpOnly: true,
      secure: true,
      sameSite: 'strict',
      path: '/',
      maxAge: 8 * 60 * 60, // 8 hours
      ...(isProd ? { domain: '.isaflow.co.za' } : {}),
    });

    // Auto-accept any pending company invitations for this email
    let invitationsAccepted = 0;
    let onboardingCompleted = !!user.onboarding_completed;

    const pendingInvitations = (await sql`
      SELECT id, company_id, role
      FROM company_invitations
      WHERE LOWER(email) = LOWER(${authUser.email})
        AND accepted_at IS NULL
        AND expires_at > NOW()
    `) as Row[];

    for (const inv of pendingInvitations) {
      await sql`
        INSERT INTO company_users (company_id, user_id, role, is_default)
        VALUES (${inv.company_id as string}::UUID, ${authUser.id}::UUID, ${inv.role as string}, false)
        ON CONFLICT (company_id, user_id) DO NOTHING
      `;
      await sql`
        UPDATE company_invitations SET accepted_at = NOW() WHERE id::TEXT = ${inv.id as string}
      `;
      invitationsAccepted++;
    }

    if (invitationsAccepted > 0 && !onboardingCompleted) {
      await sql`UPDATE users SET onboarding_completed = true WHERE id = ${authUser.id}`;
      onboardingCompleted = true;
      log.info('Onboarding skipped via invitation acceptance', { userId: authUser.id, invitationsAccepted }, 'auth/login');
    }

    // If user already belongs to a company, they're onboarded — fix stale DB flag
    if (!onboardingCompleted) {
      const companyCheck = (await sql`
        SELECT 1 FROM company_users WHERE user_id::TEXT = ${authUser.id} LIMIT 1
      `) as Row[];
      if (companyCheck.length > 0) {
        await sql`UPDATE users SET onboarding_completed = true WHERE id = ${authUser.id}`;
        onboardingCompleted = true;
        log.info('Onboarding auto-completed — user already has a company', { userId: authUser.id }, 'auth/login');
      }
    }

    // Auto-dismiss accounting tour for existing users (prevents tour on every login)
    if (onboardingCompleted) {
      await sql`
        INSERT INTO user_preferences (user_id, key, value, updated_at)
        VALUES (${authUser.id}, 'onboarding_tour_completed', 'true', NOW())
        ON CONFLICT (user_id, key) DO NOTHING
      `;
    }

    const cookies = [authCookieString];
    if (onboardingCompleted) {
      const domainSuffix = isProd ? '; Domain=.isaflow.co.za' : '';
      cookies.push(`ff_onboarding_done=1; Path=/; Max-Age=${30 * 24 * 60 * 60}; SameSite=Lax${isProd ? '; Secure' : ''}${domainSuffix}`);
    }
    res.setHeader('Set-Cookie', cookies);

    log.info('User logged in', { userId: authUser.id, email: authUser.email }, 'auth/login');

    return apiResponse.success(res, {
      user: { ...authUser, onboardingCompleted },
      invitationsAccepted,
    }, 'Login successful');
  } catch (err) {
    log.error('Login error', err instanceof Error ? { message: err.message } : { err }, 'auth/login');
    return apiResponse.internalError(res, err);
  }
}

export default withErrorHandler(handler);

/**
 * JWT Utilities
 * Token signing and verification using jose library
 */

import { SignJWT, jwtVerify, JWTPayload as JosePayload } from 'jose';
import type { JWTPayload, AuthUser, AuthRole } from './types';

// Secret key for JWT signing - must be set in environment
const getJWTSecret = (): Uint8Array => {
  const secret = process.env.JWT_SECRET;
  if (!secret || secret.length < 32) {
    throw new Error('JWT_SECRET must be set and at least 32 characters');
  }
  return new TextEncoder().encode(secret);
};

// Token expiration times
const ACCESS_TOKEN_EXPIRY = '8h'; // 8 hours — matches cookie maxAge
const _REFRESH_TOKEN_EXPIRY = '30d'; // 30 days – reserved for future refresh-token flow

/**
 * Sign a JWT token for a user
 */
export async function signToken(
  user: AuthUser,
  sessionId: string,
  expiresIn: string = ACCESS_TOKEN_EXPIRY
): Promise<string> {
  const secret = getJWTSecret();

  const token = await new SignJWT({
    email: user.email,
    role: user.role,
    sessionId,
  })
    .setProtectedHeader({ alg: 'HS256' })
    .setSubject(user.id)
    .setIssuedAt()
    .setExpirationTime(expiresIn)
    .sign(secret);

  return token;
}

/**
 * Verify and decode a JWT token
 */
export async function verifyToken(token: string): Promise<JWTPayload | null> {
  try {
    const secret = getJWTSecret();
    const { payload } = await jwtVerify(token, secret);

    // Type assertion with validation
    if (!payload.sub || !payload.email || !payload.role || !payload.sessionId) {
      return null;
    }

    return {
      sub: payload.sub as string,
      email: payload.email as string,
      role: payload.role as AuthRole,
      permissions: [], // Permissions fetched from DB via getUserAndValidateSession()
      sessionId: payload.sessionId as string,
      iat: payload.iat || 0,
      exp: payload.exp || 0,
    };
  } catch (error) {
    // Token invalid or expired
    return null;
  }
}

/**
 * Decode token without verification (internal use only — not exported).
 * Used by isTokenExpired and getTokenExpiryTime.
 */
function decodeToken(token: string): JosePayload | null {
  try {
    const parts = token.split('.');
    if (parts.length !== 3) return null;

    const part = parts[1];
    if (!part) return null;
    const payload = JSON.parse(
      Buffer.from(part, 'base64url' as BufferEncoding).toString('utf-8')
    );
    return payload;
  } catch {
    return null;
  }
}

/**
 * Check if token is expired
 */
export function isTokenExpired(token: string): boolean {
  const decoded = decodeToken(token);
  if (!decoded || !decoded.exp) return true;

  return Date.now() >= decoded.exp * 1000;
}

/**
 * Get time until token expires (in seconds)
 */
export function getTokenExpiryTime(token: string): number {
  const decoded = decodeToken(token);
  if (!decoded || !decoded.exp) return 0;

  const expiresAt = decoded.exp * 1000;
  const now = Date.now();

  return Math.max(0, Math.floor((expiresAt - now) / 1000));
}

import {
  createContext,
  useContext,
  useEffect,
  useState,
  useMemo,
  ReactNode,
  useCallback,
} from 'react';
import type { AuthRole } from '@/lib/auth/types';

/**
 * Authenticated user shape returned from /api/auth/me
 */
export interface AuthUser {
  id: string;
  email: string;
  firstName: string;
  lastName: string;
  name: string;
  role: AuthRole;
  permissions: string[];
  isActive: boolean;
  profilePicture?: string | null;
  department?: string;
  onboardingCompleted?: boolean;
}

export interface TwoFactorChallenge {
  tempToken: string;
}

interface AuthContextType {
  /** Currently authenticated user, or null if not logged in */
  user: AuthUser | null;
  /** True while the initial session check is in progress */
  loading: boolean;
  /** Last authentication error message */
  error: string | null;
  /** True when a valid user session exists */
  isAuthenticated: boolean;
  /** Set when login requires 2FA verification */
  twoFactorChallenge: TwoFactorChallenge | null;

  /** Sign in with email and password. Returns true if 2FA challenge was issued. */
  login: (email: string, password: string, deviceFingerprint?: string) => Promise<boolean>;
  /** Complete 2FA challenge during login */
  completeTwoFactor: (code: string, trustDevice?: boolean, deviceFingerprint?: string, deviceName?: string) => Promise<void>;
  /** Sign out and redirect to /sign-in */
  logout: () => Promise<void>;
  /** Re-fetch the current user from /api/auth/me */
  refreshUser: () => Promise<void>;
  /** Clear the current error state */
  clearError: () => void;

  /** Check if the user has a specific permission string */
  hasPermission: (permission: string) => boolean;
  /** Check if the user has the given role or higher */
  hasRole: (role: AuthRole) => boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

/**
 * Map the raw API response into a typed AuthUser
 */
function mapApiUser(raw: Record<string, unknown>): AuthUser {
  const firstName = (raw.firstName as string) || (raw.first_name as string) || '';
  const lastName = (raw.lastName as string) || (raw.last_name as string) || '';
  const name =
    (raw.name as string) ||
    (firstName && lastName ? `${firstName} ${lastName}`.trim() : (raw.email as string));

  return {
    id: raw.id as string,
    email: raw.email as string,
    firstName,
    lastName,
    name,
    role: (raw.role as AuthRole) || 'viewer',
    permissions: (raw.permissions as string[]) || [],
    isActive: raw.isActive !== false && raw.is_active !== false,
    profilePicture: (raw.profilePicture as string) || (raw.profile_picture as string) || null,
    department: (raw.department as string) || undefined,
    onboardingCompleted: raw.onboardingCompleted === true || raw.onboarding_completed === true,
  };
}

// Role hierarchy for permission checks
const ROLE_HIERARCHY: Record<AuthRole, number> = {
  super_admin: 6,
  system: 5,
  admin: 4,
  manager: 3,
  storeman: 2,
  technician: 2,
  viewer: 1,
};

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [twoFactorChallenge, setTwoFactorChallenge] = useState<TwoFactorChallenge | null>(null);

  /**
   * Fetch current session from the API
   */
  const checkAuth = useCallback(async () => {
    try {
      const res = await fetch('/api/auth/me', { credentials: 'include' });

      if (res.ok) {
        const data = await res.json();
        // Support both { data: { user } } and { data: user } shapes
        const raw = data.data?.user ?? data.data ?? data.user;
        if (raw) {
          setUser(mapApiUser(raw));
        } else {
          setUser(null);
        }
      } else {
        setUser(null);
      }
    } catch {
      setUser(null);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    checkAuth();

    // Re-fetch user when tab regains focus (picks up RBAC changes)
    const onFocus = () => checkAuth();
    window.addEventListener('focus', onFocus);

    // Also poll every 5 minutes as a fallback
    const interval = setInterval(checkAuth, 5 * 60 * 1000);

    return () => {
      window.removeEventListener('focus', onFocus);
      clearInterval(interval);
    };
  }, [checkAuth]);

  /**
   * Sign in with email/password credentials.
   * If 2FA is enabled, sets twoFactorChallenge and does NOT set user.
   * Returns true if a 2FA challenge was issued, false if login completed.
   */
  const login = async (email: string, password: string, deviceFingerprint?: string): Promise<boolean> => {
    setLoading(true);
    setError(null);
    setTwoFactorChallenge(null);

    try {
      const res = await fetch('/api/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password, deviceFingerprint }),
        credentials: 'include',
      });

      const data = await res.json();

      if (!res.ok) {
        throw new Error(data.error?.message || data.message || 'Login failed');
      }

      // 2FA required — store temp token for the challenge step
      if (data.data?.requiresTwoFactor) {
        setTwoFactorChallenge({ tempToken: data.data.tempToken as string });
        return true;
      }

      const raw = data.data?.user ?? data.data ?? data.user;
      setUser(raw ? mapApiUser(raw) : null);
      return false;
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Login failed';
      setError(message);
      throw err;
    } finally {
      setLoading(false);
    }
  };

  /**
   * Complete 2FA challenge — verify code and obtain full session.
   */
  const completeTwoFactor = async (
    code: string,
    trustDevice?: boolean,
    deviceFingerprint?: string,
    deviceName?: string
  ) => {
    if (!twoFactorChallenge) throw new Error('No 2FA challenge active');

    setLoading(true);
    setError(null);

    try {
      const res = await fetch('/api/auth/2fa-verify', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          tempToken: twoFactorChallenge.tempToken,
          code,
          trustDevice,
          deviceFingerprint,
          deviceName,
        }),
        credentials: 'include',
      });

      const data = await res.json();

      if (!res.ok) {
        throw new Error(data.error?.message || data.message || 'Invalid code');
      }

      setTwoFactorChallenge(null);
      const raw = data.data?.user ?? data.data ?? data.user;
      setUser(raw ? mapApiUser(raw) : null);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Verification failed';
      setError(message);
      throw err;
    } finally {
      setLoading(false);
    }
  };

  /**
   * Sign out and clear session cookie
   */
  const logout = async () => {
    try {
      await fetch('/api/auth/logout', {
        method: 'POST',
        credentials: 'include',
      });
    } finally {
      setUser(null);
      if (typeof window !== 'undefined') {
        window.location.href = '/login';
      }
    }
  };

  const refreshUser = async () => {
    await checkAuth();
  };

  const clearError = () => {
    setError(null);
  };

  /**
   * Check if the current user holds a specific permission string.
   * Users with the 'all' permission pass all checks.
   */
  const hasPermission = (permission: string): boolean => {
    if (!user) return false;
    return user.permissions.includes('all') || user.permissions.includes(permission);
  };

  /**
   * Check if the current user's role meets or exceeds the required role level.
   */
  const hasRole = (role: AuthRole): boolean => {
    if (!user) return false;
    const userLevel = ROLE_HIERARCHY[user.role] ?? 0;
    const requiredLevel = ROLE_HIERARCHY[role] ?? 0;
    return userLevel >= requiredLevel;
  };

  const value: AuthContextType = useMemo(() => ({
    user,
    loading,
    error,
    isAuthenticated: user !== null,
    twoFactorChallenge,
    login,
    completeTwoFactor,
    logout,
    refreshUser,
    clearError,
    hasPermission,
    hasRole,
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }), [user, loading, error, twoFactorChallenge]);

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}

