}

export interface CompanyUser {
  companyId: string;
  companyName: string;
  role: string;
  isDefault: boolean;
}

interface CompanyContextType {
  activeCompany: Company | null;
  companies: CompanyUser[];
  loading: boolean;
  companyRole: string | null;
  switchCompany: (companyId: string) => Promise<void>;
}

const CompanyContext = createContext<CompanyContextType | undefined>(undefined);

export function CompanyProvider({ children }: { children: ReactNode }) {
  const { isAuthenticated } = useAuth();
  const [activeCompany, setActiveCompany] = useState<Company | null>(null);
  const [companies, setCompanies] = useState<CompanyUser[]>([]);
  const [loading, setLoading] = useState(true);
  const [companyRole, setCompanyRole] = useState<string | null>(null);

  const loadCompanyDetails = useCallback(async (companyId: string) => {
    try {
      const res = await apiFetch(`/api/accounting/companies?id=${companyId}`);
      if (res.ok) {
        const data = await res.json();
        const c = data.data;
        if (c) {
          const company: Company = {
            id: c.id,
            name: c.name,
            tradingName: c.trading_name || c.tradingName,
            registrationNumber: c.registration_number || c.registrationNumber,
            vatNumber: c.vat_number || c.vatNumber,
            taxNumber: c.tax_number || c.taxNumber,
            addressLine1: c.address_line1 || c.addressLine1,
            addressLine2: c.address_line2 || c.addressLine2,
            city: c.city,
            province: c.province,
            postalCode: c.postal_code || c.postalCode,
            country: c.country,
            phone: c.phone,
            email: c.email,
            website: c.website,
            logoUrl: c.logo_url || c.logoUrl,
            logoData: c.logo_data || c.logoData,
            bankName: c.bank_name || c.bankName,
            bankAccountNumber: c.bank_account_number || c.bankAccountNumber,
            bankBranchCode: c.bank_branch_code || c.bankBranchCode,
            bankAccountType: c.bank_account_type || c.bankAccountType,
            financialYearStart: c.financial_year_start || c.financialYearStart,
            vatPeriod: c.vat_period || c.vatPeriod,
            defaultCurrency: c.default_currency || c.defaultCurrency,
            isActive: c.is_active ?? c.isActive ?? true,
          };
          setActiveCompany(company);
          localStorage.setItem(STORAGE_KEY, JSON.stringify({ id: company.id, name: company.name }));
          return company;
        }
      }
    } catch (e) {
      log.warn('Failed to load company details', { error: e }, 'context');
    }
    return null;
  }, []);

  const loadUserCompanies = useCallback(async () => {
    if (!isAuthenticated) {
      setLoading(false);
      return;
    }

    try {
      const res = await apiFetch('/api/accounting/companies?action=user-companies');

      if (!res.ok) {
        setLoading(false);
        return;
      }

      const data = await res.json();
      const raw = data.data?.items ?? data.data ?? [];
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const list: CompanyUser[] = (Array.isArray(raw) ? raw : []).map((c: any) => ({
        companyId: (c.companyId || c.company_id) as string,
        companyName: (c.companyName || c.company_name) as string,
        role: c.role as string,
        isDefault: Boolean(c.isDefault ?? c.is_default ?? false),
      }));

      setCompanies(list);

      if (list.length === 0) {
        // User has no companies — clear any stale localStorage
        localStorage.removeItem(STORAGE_KEY);
        setActiveCompany(null);
        setLoading(false);
        return;
      }

      // Determine which company to activate
      let targetId: string | null = null;

      // 1. Check localStorage
      try {
        const stored = localStorage.getItem(STORAGE_KEY);
        if (stored) {
          const { id } = JSON.parse(stored);
          if (id && list.some((c: CompanyUser) => c.companyId === id)) {
            targetId = id;
          }
        }
      } catch (e) {
        log.warn('Failed to parse stored company data', { error: e }, 'context');
      }

      // 2. Fall back to default company
      if (!targetId) {
        const defaultCompany = list.find((c: CompanyUser) => c.isDefault) ?? list[0];
        targetId = defaultCompany?.companyId ?? null;
      }

      if (!targetId) {
        setLoading(false);
        return;
      }

      // Set the role
      const match = list.find((c: CompanyUser) => c.companyId === targetId);
      if (match) setCompanyRole(match.role);

      await loadCompanyDetails(targetId);
    } catch (e) {
      log.warn('Failed to load user companies', { error: e }, 'context');
    } finally {
      setLoading(false);
    }
  }, [isAuthenticated, loadCompanyDetails]);

  useEffect(() => {
    loadUserCompanies();
  }, [loadUserCompanies]);

  const switchCompany = useCallback(async (companyId: string) => {
    setLoading(true);
    const match = companies.find(c => c.companyId === companyId);
    if (match) setCompanyRole(match.role);
    await loadCompanyDetails(companyId);
    setLoading(false);

    // Set as default on the server
    try {
      await apiFetch('/api/accounting/companies', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'set-default', companyId }),
      });
    } catch (e) {
      log.warn('Failed to persist default company switch', { error: e }, 'context');
    }
  }, [companies, loadCompanyDetails]);

  const value = useMemo<CompanyContextType>(
    () => ({ activeCompany, companies, loading, companyRole, switchCompany }),
    [activeCompany, companies, loading, companyRole, switchCompany],
  );

  return <CompanyContext.Provider value={value}>{children}</CompanyContext.Provider>;
}

export function useCompany() {
  const context = useContext(CompanyContext);
  if (context === undefined) {
    throw new Error('useCompany must be used within a CompanyProvider');
  }
  return context;
}

/**
 * Next.js Edge Middleware
 * - admin.isaflow.co.za: serve /admin/* pages with super_admin auth verification
 * - app.isaflow.co.za: redirect / to /accounting (app domain — no landing page)
 * - isaflow.co.za: show landing page at /
 * - Redirects /admin/* on non-admin hosts to admin.isaflow.co.za
 * - Redirects unauthenticated /accounting/* and /payroll/* requests to /login
 */

import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';
import { jwtVerify } from 'jose';

const AUTH_COOKIE_NAME = 'ff_auth_token';

// Sentinel used when JWT_SECRET is absent — any token verified against this will
// always fail the role check, giving defense-in-depth without crashing the edge runtime.
const MISSING_SECRET_SENTINEL = '__MIDDLEWARE_NO_SECRET__';

const getJWTSecret = (): Uint8Array => {
  const secret = process.env.JWT_SECRET;
  // Return sentinel instead of empty string so jwtVerify still runs but produces
  // a payload that cannot match a real token signed with the real secret.
  return new TextEncoder().encode(secret ?? MISSING_SECRET_SENTINEL);
};

const PUBLIC_PATHS = [
  '/login',
  '/register',
  '/api/auth/login',
  '/api/auth/logout',
  '/api/auth/register',
  '/onboarding',
  '/api/onboarding',
  '/invite',
  '/api/invite',
];

/** Hostnames that should skip the landing page and go straight to the app */
const APP_HOSTS = ['app.isaflow.co.za'];

/** Hostnames that serve the /admin platform */
const ADMIN_HOSTS = ['admin.isaflow.co.za'];

/** Paths that bypass auth checks on the admin subdomain.
 *  NOTE: '/api/' routes pass through without rewriting (they use withAdmin
 *  middleware on each handler for auth). Only page paths get rewritten. */
const ADMIN_PASSTHROUGH = [
  '/_next',
  '/login',
  '/register',
  '/favicon.ico',
  '/icons',
  '/manifest.json',
  '/sw.js',
];

const ADMIN_URL = process.env.NEXT_PUBLIC_ADMIN_URL ?? 'https://admin.isaflow.co.za';

async function verifyAdmin(token: string): Promise<boolean> {
  // Reject immediately if JWT_SECRET is not configured — never allow access
  // with a missing secret, regardless of what the token contains.
  if (!process.env.JWT_SECRET) return false;
  try {
    const { payload } = await jwtVerify(token, getJWTSecret());
    return payload.role === 'super_admin';
  } catch {
    return false;
  }
}

export async function middleware(request: NextRequest) {
  const { pathname } = request.nextUrl;
  const host = request.headers.get('host')?.split(':')[0] ?? '';

  const isAdminHost = ADMIN_HOSTS.includes(host);

  // ── Admin subdomain handling ─────────────────────────────────────────────────
  if (isAdminHost) {
    // Always passthrough for static assets, login page, and API routes
    // API routes must not be rewritten — they live at /api/*, not /admin/api/*
    if (
      ADMIN_PASSTHROUGH.some(p => pathname.startsWith(p)) ||
      pathname.startsWith('/api/') ||
      pathname.match(/\.\w+$/)  // static files (logo.png, etc.)
    ) {
      return NextResponse.next();
    }

    // Verify super_admin auth for all other paths (page navigations)
    const adminToken = request.cookies.get(AUTH_COOKIE_NAME)?.value;
    if (!adminToken) {
      const loginUrl = new URL('/login', request.url);
      loginUrl.searchParams.set('returnTo', pathname);
      return NextResponse.redirect(loginUrl);
    }

    const isAdmin = await verifyAdmin(adminToken);
    if (!isAdmin) {
      return NextResponse.redirect(new URL('/login', request.url));
    }

    // Rewrite page paths: / → /admin, /companies → /admin/companies, etc.
    if (!pathname.startsWith('/admin')) {
      const rewrittenUrl = request.nextUrl.clone();
      rewrittenUrl.pathname = pathname === '/' ? '/admin' : `/admin${pathname}`;
      return NextResponse.rewrite(rewrittenUrl);
    }

    return NextResponse.next();
  }

  // ── Non-admin hosts: redirect /admin/* to admin subdomain ───────────────────
  if (pathname.startsWith('/admin')) {
    const adminPath = pathname.replace(/^\/admin/, '') || '/';
    return NextResponse.redirect(`${ADMIN_URL}${adminPath}`);
  }

  // Allow public paths, static files, and API routes on main domains
  if (
    PUBLIC_PATHS.some(p => pathname.startsWith(p)) ||
    pathname.startsWith('/_next') ||
    pathname.startsWith('/api/') ||
    pathname.startsWith('/icons') ||
    pathname.startsWith('/landing') ||
    pathname === '/manifest.json' ||
    pathname === '/sw.js' ||
    pathname === '/favicon.ico'
  ) {
    return NextResponse.next();
  }

  // app.isaflow.co.za: redirect root to /accounting
  if (pathname === '/' && APP_HOSTS.includes(host)) {
    return NextResponse.redirect(new URL('/accounting', request.url));
  }

  // Check for auth cookie on protected routes
  const token = request.cookies.get(AUTH_COOKIE_NAME)?.value;

  if (!token && (pathname.startsWith('/accounting') || pathname.startsWith('/payroll'))) {
    const loginUrl = new URL('/login', request.url);
    loginUrl.searchParams.set('returnTo', pathname);
    return NextResponse.redirect(loginUrl);
  }

  // Redirect to onboarding if user hasn't completed it
  if (token && !request.cookies.get('ff_onboarding_done')?.value) {
    if (pathname.startsWith('/accounting') || pathname.startsWith('/payroll')) {
      return NextResponse.redirect(new URL('/onboarding', request.url));
    }
  }

  return NextResponse.next();
}

export const config = {
  matcher: ['/((?!_next/static|_next/image|favicon.ico).*)'],
};

/**
 * GET /api/auth/me
 * Returns the currently authenticated user from the JWT cookie.
 * Uses a single JOIN query for performance (session + user in one round-trip).
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { log } from '@/lib/logger';
import { apiResponse } from '@/lib/apiResponse';
import { verifyToken } from '@/lib/auth/jwt';
import { getUserAndValidateSession, AUTH_COOKIE_NAME } from '@/lib/auth/middleware';
import { createHash } from 'crypto';
import { withErrorHandler } from '@/lib/api-error-handler';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['GET']);
  }

  // Extract token from cookie or Authorization header
  const cookieToken = req.cookies[AUTH_COOKIE_NAME];
  const authHeader = req.headers.authorization;
  const bearerToken = authHeader?.startsWith('Bearer ') ? authHeader.substring(7) : null;
  const token = cookieToken ?? bearerToken;

  if (!token) {
    return res.status(401).json({
      success: false,
      error: { code: 'UNAUTHORIZED', message: 'Not authenticated' },
    });
  }

  try {
    const payload = await verifyToken(token);
    if (!payload) {
      return res.status(401).json({
        success: false,
        error: { code: 'INVALID_TOKEN', message: 'Invalid or expired token' },
      });
    }

    const tokenHash = createHash('sha256').update(token).digest('hex');
    const user = await getUserAndValidateSession(payload.sub, payload.sessionId, tokenHash);

    if (!user) {
      return res.status(401).json({
        success: false,
        error: { code: 'SESSION_INVALID', message: 'Session expired or invalid' },
      });
    }

    return apiResponse.success(res, { user });
  } catch (err) {
    log.error('Failed to get current user', err instanceof Error ? { message: err.message } : { err }, 'auth/me');
    return apiResponse.internalError(res, err);
  }
}

export default withErrorHandler(handler);

