                  <tbody>
                    {companies.length === 0 && <tr><td colSpan={3} className="px-4 py-8 text-center text-gray-400">No companies</td></tr>}
                    {companies.map(c => (
                      <tr key={c.id} className="border-b border-gray-100 dark:border-gray-800 last:border-0">
