                              confirmAction === `delink-${c.company_id}` ? 'bg-red-500 text-white' : 'text-red-500 hover:bg-red-50 dark:hover:bg-red-500/10'}`}>
                            <Trash2 className="w-3.5 h-3.5" /> {confirmAction === `delink-${c.company_id}` ? 'Sure?' : 'Remove'}
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </>
      )}
    </AdminLayout>
  );
}

