city, 4-digit postalCode, and province as separate fields. Do NOT concatenate them into one line. \
\
Respond with only the JSON object.`;

// ── Extracted data type ───────────────────────────────────────────────────────

interface ExtractedDirector {
  name: string;
  idNumber: string;
  role: string;
}

interface ExtractedCompany {
  name: string;
  tradingName: string;
  registrationNumber: string;
  vatNumber: string;
  taxNumber: string;
  addressLine1: string;
  addressLine2: string;
  city: string;
  province: string;
  postalCode: string;
  country: string;
  phone: string;
  email: string;
  website: string;
