// - Already has a company → /accounting
const postRegisterRedirect = async (): Promise<string> => {
  if (inviteToken) {
    try {
      const acceptRes = await fetch(`/api/invite/${inviteToken}`, {
        method: 'POST',
        credentials: 'include',
      });
      if (acceptRes.ok) {
        // Invitation accepted — the user is now in the inviting company.
        return '/accounting';
