        if (compRes.ok) {
          const compBody = (await compRes.json()) as { data?: { items?: unknown[] } };
          if ((compBody.data?.items ?? []).length > 0) return '/accounting';
        }
      } catch {
        // Ignore — fall through to error surfacing.
      }
      // Genuinely failed: show the server message and stop on this page.
      const body = (await acceptRes.json().catch(() => ({}))) as {
        error?: { message?: string };
      };
      setError(
        body.error?.message ??
          'Could not accept the invitation. It may have expired or been sent to a different email.',
      );
      return null;
    } catch {
      // Network error on accept — non-fatal, let them into the app via
      // the generic post-register destination logic below.
    }
  }

