import {
  bankTransactionHash,
  type HashableTransaction,
} from '@/modules/accounting/utils/bankTransactionHash';
import { compareBankAccountNumbers } from '@/modules/accounting/utils/bankAccountNumberMatch';
import type {
  BankCsvParseResult,
  BankFormat,
  ParsedBankTransaction,
} from '@/modules/accounting/types/bank.types';

// ── Rule matching (in-memory, mirrors bankRulesService SQL semantics) ────────

interface RuleRow {
  id: string;
  match_field: 'description' | 'reference' | 'both';
  match_type: 'contains' | 'starts_with' | 'ends_with' | 'exact';
  match_pattern: string;
  is_active: boolean;
}

function ruleMatchesTransaction(rule: RuleRow, tx: ParsedBankTransaction): boolean {
  const pattern = rule.match_pattern.toLowerCase();
  const fields: string[] = [];
  if (rule.match_field === 'description' || rule.match_field === 'both') {
    fields.push((tx.description ?? '').toLowerCase());
  }
  if (rule.match_field === 'reference' || rule.match_field === 'both') {
    fields.push((tx.reference ?? '').toLowerCase());
  }
  return fields.some(f => {
    switch (rule.match_type) {
      case 'contains':    return f.includes(pattern);
      case 'starts_with': return f.startsWith(pattern);
      case 'ends_with':   return f.endsWith(pattern);
      case 'exact':       return f === pattern;
      default:            return false;
    }
  });
}

// ── Parsing dispatch (shared with commit endpoint in spirit) ─────────────────

async function parseStatement(args: {
  fileType: 'pdf' | 'csv' | 'ofx' | 'qif';
  pdfBase64?: string;
  csvContent?: string;
  bankFormat?: BankFormat;
}): Promise<BankCsvParseResult> {
  const { fileType, pdfBase64, csvContent, bankFormat } = args;

  if (fileType === 'pdf') {
    if (!pdfBase64) {
      throw new Error('pdfBase64 is required for PDF imports');
    }
    const base64Data = pdfBase64.includes(',') ? pdfBase64.split(',')[1]! : pdfBase64;
    const pdfBuffer = Buffer.from(base64Data, 'base64');
    return await parseBankPdf(pdfBuffer, bankFormat);
  }

  if (!csvContent) {
    throw new Error('csvContent is required for CSV/OFX/QIF imports');
  }

  if (fileType === 'ofx') return parseOfxStatement(csvContent);
  if (fileType === 'qif') return parseQifStatement(csvContent);

  const format = bankFormat && bankFormat !== 'unknown' ? bankFormat : detectBankFormat(csvContent);
  switch (format) {
    case 'fnb':           return parseFNBStatement(csvContent);
    case 'standard_bank': return parseStandardBankStatement(csvContent);
    case 'nedbank':       return parseNedbankStatement(csvContent);
    case 'absa':          return parseABSAStatement(csvContent);
    case 'capitec':       return parseCapitecStatement(csvContent);
    default:
      throw new Error('Unable to detect bank format. Please specify the bank.');
  }
}

// ── Handler ──────────────────────────────────────────────────────────────────

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  const { companyId } = req as CompanyApiRequest;

  const {
    pdfBase64,
    csvContent,
    fileType,
    bankFormat,
    bankAccountId: userSelectedAccountId,
